// A focused player entrance; existing training content and records remain intact.
data.journey=data.journey||{logs:{},started:[localDate(),localDate()]};
const hub=document.createElement('div');hub.id='journey';document.querySelector('main').prepend(hub);
const nav=document.createElement('nav');nav.className='journey-nav';nav.innerHTML=['Today','Learn','Progress'].map(x=>`<button data-hub="${x}">${x}</button>`).join('');document.body.append(nav);
let hubPage='Today',step=0;
function dayKey(d){return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')}
function streakInfo(){let n=0,best=0,missing=false,repair=0,marked=false;const end=new Date(localDate()+'T12:00:00');for(let d=new Date(data.journey.started[player]+'T12:00:00');d<=end;d.setDate(d.getDate()+1)){const k=dayKey(d),r=data.journey.logs[player+'|'+k];if(![1,3,5].includes(d.getDay()))continue;if(r?.kind==='Pause')continue;if(r){n++;if(missing){repair++;if(repair===2){missing=false;marked=true}}best=Math.max(best,n)}else if(k!==localDate()){missing=true;repair=0}}return {n:missing?repair:n,best,missing,repair,marked}}
function openLegacy(s){hub.hidden=true;document.body.classList.remove('hub-mode');section=s;lessonId=null;render();window.scrollTo(0,0)}
function showHub(page='Today'){pause();hubPage=page;nav.querySelectorAll('[data-hub]').forEach(b=>{if(b.dataset.hub===page)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});hub.hidden=false;document.body.classList.add('hub-mode');const st=streakInfo(),l=lessonById[prefs().focus]||lessonById.scan;hub.innerHTML=`<div class="row between"><div class="row">${data.names.map((n,i)=>`<button data-choose="${i}" class="${i===player?'primary':''}">${escapeHTML(n)}</button>`).join('')}</div><button data-parent>Parent</button></div><p class="muted">YOUR OWN PACE</p>`;
if(page==='Today')hub.innerHTML+=`<section class="journey-hero"><small>ONE IDEA. YOUR NEXT STEP.</small><h1>${escapeHTML(l.title)}</h1><p>${player===1?'See the space. Know your next move.':escapeHTML(l.cues[0])}</p><button class="primary" data-start>Start my focus →</button><p class="micro">Learn → try → use at practice</p></section><section class="panel"><h3>🔥 ${st.n} planned days together</h3><p>${st.missing?'Your comeback is ready. Complete your next two planned days—no extra workouts.':st.marked?'Comeback earned · repaired streak':'Days off do not break your streak.'}</p></section><section class="panel"><h3>Been on the field?</h3><p>Practice and games count. Tell us what you tried.</p><div class="row"><button data-log="Practice">Log practice</button><button data-log="Game">Log game</button></div></section><details class="panel"><summary>More for today</summary><p>Optional—not extra boxes you have to finish.</p><button data-old="week">My weekly training plan</button> <button data-old="strength">Strength & movement</button> <button data-old="soccer">Ball training</button></details>`;
if(page==='Learn')hub.innerHTML+=`<h1>Build your game.</h1><p>Start with your focus. Explore more when you want.</p><section class="panel"><small>YOUR CURRENT FOCUS</small><h2>${escapeHTML(l.title)}</h2><button class="primary" data-start>Continue →</button></section><div class="library-grid">${lessons.map(x=>`<button class="learn-tile" data-focus="${x.id}"><small>${escapeHTML(x.category)}</small><h3>${escapeHTML(x.title)}</h3><span>Explore →</span></button>`).join('')}</div><p><button data-old="library">Positions & 9v9 / 11v11 library</button></p>`;
if(page==='Progress'){const rows=Object.entries(data.journey.logs).filter(([k])=>k.startsWith(player+'|')).sort().reverse();hub.innerHTML+=`<h1>Your progress.</h1><section class="journey-hero"><h2>🔥 ${st.n} planned days</h2><p>Longest run: ${st.best} · ${rows.filter(([,r])=>r.kind!=='Pause').length} active days</p><p>${st.missing?'Comeback: '+st.repair+'/2 scheduled days':st.marked?'Repaired streak · comeback earned':'Keep following your plan.'}</p></section><p>Logs are your reflections, not a skill grade. Saved on this device only.</p>${rows.map(([k,r])=>`<article class="panel"><small>${k.split('|')[1]} · ${escapeHTML(r.kind)}</small><h3>${escapeHTML(r.focus||'Rest and recovery')}</h3><p>${escapeHTML(r.tried||'')} · ${escapeHTML(r.feeling||'')}</p><p>${escapeHTML(r.note||'')}</p></article>`).join('')||'<p>Your first session starts your story.</p>'}<button data-old="history">Earlier training history</button>`}window.scrollTo(0,0)}
function focusStep(){const l=lessonById[prefs().focus]||lessonById.scan;const stages=['Understand','See it','Choose','Try it','Take it to practice'];hub.innerHTML=`<button data-hub="Today">← Today</button><p class="muted">${step+1} / 5 · ${stages[step]}</p><section class="panel focus-card"><h1>${escapeHTML(l.title)}</h1>${step===0?`<p>${escapeHTML(l.why)}</p><strong>${escapeHTML(l.cues[0])}</strong>`:step===1?`<p>Watch for one thing: ${escapeHTML(l.cues[0])}</p>${l.video.map(id=>demoCatalog[id]?`<p><a target="_blank" rel="noopener" href="${demoCatalog[id].url}">▶ ${escapeHTML(demoCatalog[id].title)}</a></p>`:'').join('')}<p class="micro">Videos open on their original sites.</p>`:step===2?`<p>Before the ball reaches you, what helps you choose your next move?</p><button data-answer="look">Check where the defender and space are</button><button data-answer="wait">Wait and look after receiving</button><p id="coachReply" role="status"></p>`:step===3?`<p>Try the focus drill at a comfortable pace. Stop if something hurts.</p><button data-drill>Show my drill & demonstration →</button><p>Return to Today → Start to revisit this idea.</p>`:`<p>At your next practice, try this:</p><h2>${escapeHTML(l.cues[0])}</h2><p>Not getting a chance is okay. Noticing is part of learning.</p>`}</section><button class="primary" ${step===4?'data-log="Home session"':'data-next'}>${step===4?'Finish & reflect':'Next →'}</button>`}
function logForm(kind){hub.innerHTML=`<button data-hub="Today">← Today</button><h1>${kind}</h1><form id="quickLog" class="panel"><label>Day<input name="date" type="date" value="${localDate()}" max="${localDate()}" min="${data.journey.started[player]}" required></label><label>Did you try the idea?<select name="tried"><option>Yes</option><option>Tried but tricky</option><option>Didn't get a chance</option></select></label><label>How did you feel?<select name="feeling"><option>Fresh</option><option>Okay</option><option>Tired</option><option>Something hurts</option></select></label><label>One thing I'm proud of (optional)<textarea name="note" maxlength="500"></textarea></label><p>If something hurts, stop and tell an adult.</p><button class="primary">Save my day</button><p class="micro">One active day per date. Saving again updates that day.</p></form>`;$('quickLog').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);data.journey.logs[player+'|'+f.get('date')]={kind,tried:f.get('tried'),feeling:f.get('feeling'),note:f.get('note'),focus:lessonById[prefs().focus].title};persist();showHub('Progress')}}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset;if(d.hub)showHub(d.hub);if(d.choose!==undefined){player=Number(d.choose);step=0;showHub()}if(d.old)openLegacy(d.old);if(d.start!==undefined){step=0;focusStep()}if(d.next!==undefined){step++;focusStep()}if(d.answer)$('coachReply').textContent=d.answer==='look'?'Yes—looking early gives you time to choose.':'You can look after receiving, but pressure may arrive first. Try checking before the pass.';if(d.drill!==undefined){openLegacy('library');goLesson(prefs().focus)}if(d.log)logForm(d.log);if(d.focus){prefs().focus=d.focus;persist();step=0;focusStep()}if(d.parent!==undefined){hub.innerHTML='<button data-hub="Today">← Today</button><h1>Parent area</h1><p>Settings are not password-protected. Records remain on this browser; they do not sync across devices.</p><button data-old="week">Schedule & workload</button> <button data-old="strength">Workout settings & export</button><section class="panel"><h3>Protect a recovery day</h3><p>Pause today for planned rest, illness or injury. This protects the run; it does not earn an active day.</p><button data-pause-day>Pause today</button></section>'}if(d.pauseDay!==undefined){data.journey.logs[player+'|'+localDate()]={kind:'Pause'};persist();showHub()}});
persist();showHub();
